package org.apache.commons.lang;

import org.junit.BeforeClass;
import org.junit.Test;

import java.util.*;

import static org.junit.Assert.*;

public class LocaleUtilsTest {

    /* --------------------------------------------------------------
     *  toLocale(String) tests
     * -------------------------------------------------------------- */
    @Test
    public void testToLocale_NullInput() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_LanguageOnly() {
        Locale locale = LocaleUtils.toLocale("en");
        assertEquals("en", locale.getLanguage());
        assertEquals("", locale.getCountry());
        assertEquals("", locale.getVariant());
    }

    @Test
    public void testToLocale_LanguageAndCountry() {
        Locale locale = LocaleUtils.toLocale("en_GB");
        assertEquals("en", locale.getLanguage());
        assertEquals("GB", locale.getCountry());
        assertEquals("", locale.getVariant());
    }

    @Test
    public void testToLocale_WithVariant() {
        Locale locale = LocaleUtils.toLocale("en_US_xxx");
        assertEquals("en", locale.getLanguage());
        assertEquals("US", locale.getCountry());
        assertEquals("xxx", locale.getVariant());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLength() {
        LocaleUtils.toLocale("e");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLanguageCase() {
        LocaleUtils.toLocale("EN");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidCountryCase() {
        LocaleUtils.toLocale("en_gb");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_MissingUnderscore() {
        LocaleUtils.toLocale("enGB");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_ExtraUnderscoreWithoutVariant() {
        LocaleUtils.toLocale("en_US_");
    }

    /* --------------------------------------------------------------
     *  localeLookupList(Locale) tests
     * -------------------------------------------------------------- */
    @Test
    public void testLocaleLookupList_NullLocale() {
        List<Locale> list = LocaleUtils.localeLookupList(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testLocaleLookupList_SimpleLocale() {
        Locale locale = new Locale("fr");
        List<Locale> list = LocaleUtils.localeLookupList(locale);
        assertEquals(1, list.size());
        assertEquals(locale, list.get(0));
    }

    @Test
    public void testLocaleLookupList_WithCountry() {
        Locale locale = new Locale("fr", "CA");
        List<Locale> list = LocaleUtils.localeLookupList(locale);
        assertEquals(2, list.size());
        assertEquals(locale, list.get(0));
        assertEquals(new Locale("fr", ""), list.get(1));
    }

    @Test
    public void testLocaleLookupList_WithVariant() {
        Locale locale = new Locale("fr", "CA", "xxx");
        List<Locale> list = LocaleUtils.localeLookupList(locale);
        assertEquals(3, list.size());
        assertEquals(locale, list.get(0));
        assertEquals(new Locale("fr", "CA"), list.get(1));
        assertEquals(new Locale("fr", ""), list.get(2));
    }

    /* --------------------------------------------------------------
     *  localeLookupList(Locale, Locale) tests
     * -------------------------------------------------------------- */
    @Test
    public void testLocaleLookupList_WithDefault_NotDuplicated() {
        Locale locale = new Locale("fr", "CA", "xxx");
        Locale defaultLocale = new Locale("fr", "CA", "xxx"); // same as first
        List<Locale> list = LocaleUtils.localeLookupList(locale, defaultLocale);
        // default must not be added a second time
        assertEquals(3, list.size());
        assertEquals(locale, list.get(0));
        assertEquals(new Locale("fr", "CA"), list.get(1));
        assertEquals(new Locale("fr", ""), list.get(2));
    }

    @Test
    public void testLocaleLookupList_WithDefault_Additional() {
        Locale locale = new Locale("fr", "CA", "xxx");
        Locale defaultLocale = new Locale("en");
        List<Locale> list = LocaleUtils.localeLookupList(locale, defaultLocale);
        assertEquals(4, list.size());
        assertEquals(defaultLocale, list.get(3));
    }

    /* --------------------------------------------------------------
     *  availableLocaleList() tests
     * -------------------------------------------------------------- */
    @Test
    public void testAvailableLocaleList_Unmodifiable() {
        List<Locale> list = LocaleUtils.availableLocaleList();
        assertNotNull(list);
        assertEquals(Arrays.asList(Locale.getAvailableLocales()), list);
        try {
            list.add(Locale.CANADA);
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException ignored) {
        }
    }

    /* --------------------------------------------------------------
     *  availableLocaleSet() tests
     * -------------------------------------------------------------- */
    @Test
    public void testAvailableLocaleSet_Unmodifiable() {
        Set<Locale> set = LocaleUtils.availableLocaleSet();
        assertNotNull(set);
        assertTrue(set.containsAll(Arrays.asList(Locale.getAvailableLocales())));
        try {
            set.add(Locale.CANADA);
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException ignored) {
        }
    }

    @Test
    public void testAvailableLocaleSet_CachedInstance() {
        Set<Locale> first = LocaleUtils.availableLocaleSet();
        Set<Locale> second = LocaleUtils.availableLocaleSet();
        assertSame(first, second); // should be the same cached set
    }

    /* --------------------------------------------------------------
     *  isAvailableLocale(Locale) tests
     * -------------------------------------------------------------- */
    @Test
    public void testIsAvailableLocale_KnownLocale() {
        Locale known = Locale.US; // always present
        assertTrue(LocaleUtils.isAvailableLocale(known));
    }

    @Test
    public void testIsAvailableLocale_UnknownLocale() {
        Locale unknown = new Locale("xx", "XX");
        // depending on the JRE, this may or may not be present; we assert based on the set content
        boolean expected = LocaleUtils.availableLocaleSet().contains(unknown);
        assertEquals(expected, LocaleUtils.isAvailableLocale(unknown));
    }

    /* --------------------------------------------------------------
     *  languagesByCountry(String) tests
     * -------------------------------------------------------------- */
    @Test
    public void testLanguagesByCountry_Null() {
        List<Locale> list = LocaleUtils.languagesByCountry(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testLanguagesByCountry_KnownCountry() {
        // Use a country that is guaranteed to exist in the JRE, e.g., "US"
        List<Locale> list = LocaleUtils.languagesByCountry("US");
        assertNotNull(list);
        assertFalse(list.isEmpty());
        for (Locale l : list) {
            assertEquals("US", l.getCountry());
            assertEquals(0, l.getVariant().length());
        }
        // verify caching – second call returns the same (==) object
        List<Locale> second = LocaleUtils.languagesByCountry("US");
        assertSame(list, second);
    }

    @Test
    public void testLanguagesByCountry_Unmodifiable() {
        List<Locale> list = LocaleUtils.languagesByCountry("US");
        try {
            list.add(Locale.US);
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException ignored) {
        }
    }

    /* --------------------------------------------------------------
     *  countriesByLanguage(String) tests
     * -------------------------------------------------------------- */
    @Test
    public void testCountriesByLanguage_Null() {
        List<Locale> list = LocaleUtils.countriesByLanguage(null);
        assertNotNull(list);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_KnownLanguage() {
        // "en" is a very common language code
        List<Locale> list = LocaleUtils.countriesByLanguage("en");
        assertNotNull(list);
        assertFalse(list.isEmpty());
        for (Locale l : list) {
            assertEquals("en", l.getLanguage());
            assertTrue(l.getCountry().length() > 0);
            assertEquals(0, l.getVariant().length());
        }
        // verify caching
        List<Locale> second = LocaleUtils.countriesByLanguage("en");
        assertSame(list, second);
    }

    @Test
    public void testCountriesByLanguage_Unmodifiable() {
        List<Locale> list = LocaleUtils.countriesByLanguage("en");
        try {
            list.remove(0);
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException ignored) {
        }
    }

    /* --------------------------------------------------------------
     *  Constructor – just ensure it can be instantiated (even though not needed)
     * -------------------------------------------------------------- */
    @Test
    public void testConstructorIsPublic() {
        LocaleUtils utils = new LocaleUtils();
        assertNotNull(utils);
    }
}
